#!/usr/bin/env python3
'''Standalone CPU check for K-FW-001.
Checks a conceptual mode-state machine, autograd boundary guard,
request-local draws, and a saved-activation cost identity.
Only sys is imported; no project or upstream implementation is used.
'''
import sys

MASK = (1 << 64) - 1


class IllegalMode(Exception):
    pass


def new_ctx(training=True, grad=True):
    return {'training': bool(training), 'grad': bool(grad), 'depth': 0}


def enter_region(ctx, kind):
    if kind not in ('record', 'no_grad', 'inference'):
        raise ValueError('bad kind')
    saved = {'training': ctx['training'], 'grad': ctx['grad'], 'depth': ctx['depth']}
    if kind == 'record':
        if ctx['depth'] > 0:
            raise IllegalMode('record inside inference')
        ctx['grad'] = True
    elif kind == 'no_grad':
        ctx['grad'] = False
    else:
        ctx['depth'] += 1
        ctx['grad'] = False
    return saved


def leave_region(ctx, saved):
    if ctx['training'] != saved['training']:
        raise AssertionError('training changed by region')
    ctx['grad'] = saved['grad']
    ctx['depth'] = saved['depth']


def enter_region_faulty(ctx, kind):
    saved = {'training': ctx['training'], 'grad': ctx['grad'], 'depth': ctx['depth']}
    if kind == 'record':
        ctx['grad'] = True
    elif kind == 'no_grad':
        ctx['grad'] = False
    else:
        ctx['depth'] += 1
        ctx['grad'] = False
    return saved


def leave_region_faulty_training(ctx, saved, wrong_training):
    ctx['grad'] = saved['grad']
    ctx['depth'] = saved['depth']
    ctx['training'] = bool(wrong_training)


def check_consumer(provenance, materialized, requires_grad):
    if provenance == 'inference' and requires_grad and not materialized:
        raise IllegalMode('inference tensor passed to autograd')
    return True


def check_consumer_faulty(provenance, materialized, requires_grad):
    return True


def activation_bytes(items):
    return sum(n * b for n, b in items) + 16 * len(items)


def activation_bytes_faulty(items):
    return sum(n for n, _ in items) + 16 * len(items)


def mix64(x):
    x = x & MASK
    x = (x + 0x9E3779B97F4A7C15) & MASK
    z = x
    z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & MASK
    z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & MASK
    return (z ^ (z >> 31)) & MASK


def draw(seed, req, pos):
    key = mix64((seed & MASK) ^ ((req + 0x9E3779B97F4A7C15) & MASK))
    return mix64(key ^ (((pos + 1) * 0x9E3779B97F4A7C15) & MASK))


def sequence(seed, req, n):
    return [draw(seed, req, i) for i in range(n)]


def interleaved(seed, reqs, n):
    out = {r: [] for r in reqs}
    pos = {r: 0 for r in reqs}
    for _ in range(n):
        for r in reqs:
            out[r].append(draw(seed, r, pos[r]))
            pos[r] += 1
    return out


class BadGlobal:
    def __init__(self, seed):
        self.state = mix64(seed)

    def next(self):
        self.state = mix64(self.state ^ 0xD1B54A32D192ED03)
        return self.state


def bad_alone(seed, n):
    g = BadGlobal(seed)
    return [g.next() for _ in range(n)]


def main():
    failures = []

    def check(cond, msg):
        if cond:
            print('OK ' + msg)
        else:
            print('FAIL ' + msg)
            failures.append(msg)

    def obs(msg):
        print('OBS ' + msg)

    start = new_ctx(True, True)
    ctx = new_ctx(True, True)
    s1 = enter_region(ctx, 'inference')
    check(ctx['grad'] is False and ctx['depth'] == 1 and ctx['training'] is True,
          'inference disables grad and leaves training unchanged')
    s2 = enter_region(ctx, 'no_grad')
    check(ctx['grad'] is False and ctx['depth'] == 1 and ctx['training'] is True,
          'nested no_grad keeps inference depth')
    leave_region(ctx, s2)
    check(ctx['grad'] is False and ctx['depth'] == 1 and ctx['training'] is True,
          'leaving no_grad restores inference context')
    leave_region(ctx, s1)
    check(ctx == start, 'nested contexts restore grad and depth exactly')
    obs('mode start=' + repr(start))

    ctx2 = new_ctx(False, False)
    enter_region(ctx2, 'inference')
    rejected = False
    try:
        enter_region(ctx2, 'record')
    except IllegalMode:
        rejected = True
    check(rejected, 'record inside inference is rejected by the correct guard')

    bad = new_ctx(False, False)
    enter_region(bad, 'inference')
    faulty_accepted = False
    try:
        enter_region_faulty(bad, 'record')
        faulty_accepted = True
    except Exception:
        faulty_accepted = False
    check(faulty_accepted, 'negative control: faulty guard accepts forbidden record')

    ctx3 = new_ctx(True, True)
    saved3 = enter_region(ctx3, 'inference')
    leave_region_faulty_training(ctx3, saved3, False)
    check(ctx3['training'] is False and start['training'] is True,
          'negative control: faulty pop changes training and is distinguishable')

    guard_rejected = False
    try:
        check_consumer('inference', False, True)
    except IllegalMode:
        guard_rejected = True
    check(guard_rejected, 'inference tensor is rejected by autograd consumer guard')
    check(check_consumer('inference', True, True),
          'materialized inference-origin output can cross the boundary')
    check(check_consumer('inference', False, False),
          'a no-grad consumer is allowed')

    faulty_consumer_accepted = False
    try:
        check_consumer_faulty('inference', False, True)
        faulty_consumer_accepted = True
    except IllegalMode:
        faulty_consumer_accepted = False
    check(faulty_consumer_accepted,
          'negative control: faulty consumer guard accepts forbidden path')

    items = [(8 * 1024 * 4096, 2)] * 12
    expected = 12 * 8 * 1024 * 4096 * 2 + 12 * 16
    check(activation_bytes(items) == expected,
          'saved-activation byte identity is additive over listed tensors')
    check(activation_bytes([]) == 0, 'empty activation set has zero bytes')
    check(activation_bytes_faulty([(100, 2)]) != activation_bytes([(100, 2)]),
          'negative control: formula omitting dtype is distinguishable')
    obs('saved bytes for 12 x 64 MiB FP16 activations=' + str(activation_bytes(items)))

    seed = 20261028
    reqs = [0, (1 << 63) + 7]
    n = 7
    alone = {r: sequence(seed, r, n) for r in reqs}
    inter = interleaved(seed, reqs, n)
    check(all(alone[r] == inter[r] for r in reqs),
          'request-local draws are independent of interleaving order')
    check(sequence(seed, reqs[1], n) == sequence(seed, reqs[1], n),
          'same seed/request/position reproduces the same sequence')
    check(sequence(seed, reqs[0], n) != sequence(seed, reqs[1], n),
          'different request identities do not share one sequence')

    g = BadGlobal(seed)
    bad_inter = {r: [] for r in reqs}
    for _ in range(n):
        for r in reqs:
            bad_inter[r].append(g.next())
    bad_ref = bad_alone(seed, n)
    check(bad_inter[reqs[0]] != bad_ref,
          'negative control: one global RNG is schedule dependent')

    obs('request 0 alone first 3=' + repr(alone[reqs[0]][:3]))
    obs('request 0 interleaved first 3=' + repr(inter[reqs[0]][:3]))

    if failures:
        print('RESULT: FAIL (' + str(len(failures)) + ' checks failed)')
        return 1
    print('RESULT: PASS (mode state, consumer boundary, cost identity, request RNG; negative controls detected)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
